import type { ChoiceConfig } from '../../../db/types/Choice';
import type { PricingDetail } from '../../Variable';
/**
 * Extended ChoiceConfig type that includes pricingDetails
 */
type ExtendedChoiceConfig = ChoiceConfig & {
    pricingDetails?: PricingDetail[];
};
/**
 * Extended Choices type using the ExtendedChoiceConfig
 * Only supports full choice configuration objects, not string values
 */
export type ExtendedChoices = Record<string | number, ExtendedChoiceConfig>;
export {};
